-- 200_billing_export_jobs.sql — asynchronous/background accounting exports with expiring download links. A job is
-- created pending, processed by a worker (scheduler-compatible), and the generated bytes are stored here with a
-- download token and an expiry. Storing bytes in Postgres keeps this self-contained; production can repoint storage at
-- object storage without changing the job lifecycle. The download endpoint enforces expiry (link becomes 410 Gone).
CREATE TABLE IF NOT EXISTS billing_export_jobs (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  report         TEXT NOT NULL,
  format         TEXT NOT NULL DEFAULT 'csv',
  filters_json   JSONB NOT NULL DEFAULT '{}'::jsonb,
  status         TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','ready','failed','expired')),
  row_count      INTEGER,
  filename       TEXT,
  content_type   TEXT,
  content_b64    TEXT,               -- generated file bytes (base64) or CSV text; cleared on expiry
  download_token TEXT NOT NULL UNIQUE,
  error          TEXT,
  created_by_user_id UUID,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at   TIMESTAMPTZ,
  expires_at     TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_billing_export_jobs_status ON billing_export_jobs (status, created_at);
